100:     for(let i=0;i<flowers.length;i++)if(!state.petals.includes(i)){const f=flowers[i],blink=(Math.sin(now/260+i*2)+1)/2;ctx.fillStyle=`rgba(255,244,187,${.35+blink*.35})`;ctx.fillRect(f.x-5,f.y-9,1,1);ctx.fillRect(f.x+6,f.y-5,1,1);ctx.fillStyle='#fff4c2';ctx.fillRect(f.x+5,f.y-10,1,1)}
