104:   function solid(x,y){if(x<12||y<12||x>MW-12||y>MH-12)return true;const pond=((x-194)/89)**2+((y-184)/62)**2<1; if(pond)return true;if(x>653&&x<750&&y>153&&y<230)return true;if(x>441&&x<478&&y>240&&y<279)return true;for(const [tx,ty,s] of trees){if(Math.abs(x-tx)<13*s&&Math.abs(y-(ty+1))<10*s)return true}return Math.hypot(x-514,y-359)<12;}
