111:   function direction(){let x=0,y=0;if(keys.has('ArrowLeft')||keys.has('a'))x--;if(keys.has('ArrowRight')||keys.has('d'))x++;if(keys.has('ArrowUp')||keys.has('w'))y--;if(keys.has('ArrowDown')||keys.has('s'))y++;return {x,y}}
112:   function update(dt){const d=direction(),moving=d.x||d.y;if(moving){const len=Math.hypot(d.x,d.y),speed=78*dt,dx=d.x/len*speed,dy=d.y/len*speed;if(d.x<0)state.face='left';if(d.x>0)state.face='right';if(d.y<0)state.face='up';if(d.y>0)state.face='down';if(!solid(state.x+dx,state.y))state.x+=dx;if(!solid(state.x,state.y+dy))state.y+=dy;walkPhase+=dt*13;state.elapsed+=dt}if(moving)save();}
