118:   function renderRoadmap(){const list=document.getElementById('step-list');list.innerHTML='';stepData.forEach((step,i)=>{const li=document.createElement('li');li.className='step '+(i===0?'current':'');li.innerHTML=`<span class="step-num">0${i+1}</span><div class="step-copy"><div class="step-title"></div><div class="step-note"></div></div>`;li.querySelector('.step-title').textContent=step.title;li.querySelector('.step-note').textContent=step.note;list.append(li)})}
119:   const modal=document.getElementById('roadmap-modal');function openEditor(){const rows=document.getElementById('edit-rows');rows.innerHTML='';stepData.forEach((step,i)=>{const row=document.createElement('div');row.className='edit-row';row.innerHTML=`<span class="step-num">0${i+1}</span><div><label>Step ${i+1} title</label><input maxlength="42" data-title="${i}"/><label style="margin-top:8px">Description</label><textarea maxlength="100" data-note="${i}"></textarea></div>`;row.querySelector('input').value=step.title;row.querySelector('textarea').value=step.note;rows.append(row)});modal.classList.add('open')}
120:   document.getElementById('edit-steps').addEventListener('click',openEditor);document.getElementById('close-modal').addEventListener('click',()=>modal.classList.remove('open'));modal.addEventListener('pointerdown',e=>{if(e.target===modal)modal.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')modal.classList.remove('open')});document.getElementById('save-roadmap').addEventListener('click',()=>{stepData=stepData.map((s,i)=>({title:document.querySelector(`[data-title="${i}"]`).value.trim()||defaultSteps[i].title,note:document.querySelector(`[data-note="${i}"]`).value.trim()||defaultSteps[i].note,status:i===0?'current':'next'}));saveRoadmap();renderRoadmap();modal.classList.remove('open')});document.getElementById('reset-roadmap').addEventListener('click',()=>{stepData=structuredClone(defaultSteps);saveRoadmap();renderRoadmap();openEditor()});
121:   load();renderRoadmap();refreshQuest();requestAnimationFrame(render);
122:   </script>
123: </body>
