function refreshQuest(){const n=state.petals.length;document.getElementById('petal-count').textContent=`${n} / 3`;document.getElementById('petal-meter').style.width=`${n/3*100}%`;document.getElementById('objective-text').textContent=state.wellDone?'The bell has answered. Something below stirs.':n===3?'Carry the three death-tolls to the chapel altar':'Recover three death-tolls for the chapel bell';}
function interact(){let best=-1,dist=Infinity;flowers.forEach((f,i)=>{if(!state.petals.includes(i)){const d=Math.hypot(state.x-f.x,state.y-f.y);if(d<dist){dist=d;best=i}}});if(best>=0&&dist<31){state.petals.push(best);save();refreshQuest();showToast(state.petals.length===3?'Three iron tolls. The chapel bell waits in the rain.':'A cold iron death-toll. Its inscription has been scraped away.');return}
  const wellDist=Math.hypot(state.x-460,state.y-261);if(wellDist<40){if(state.wellDone){showToast('The bell is silent. Beneath the altar, stone grinds against stone.');return}if(state.petals.length>=3){state.wellDone=true;save();refreshQuest();showToast('The bell tolls once. No hand touched its rope.');return}showToast(`The altar is incomplete. ${3-state.petals.length} death-toll${state.petals.length===2?'':'s'} remain in the graves.`);return}
  if(Math.hypot(state.x-514,state.y-359)<38){showToast(state.petals.length>=3?'Edda: Put them on the altar. And do not answer if it calls your name.':'Edda: Three tolls were buried with the parish dead. I heard one ring last night.');return}showToast('Rain, ash, and the distant sound of a bell.');
}

