function interact(){if(state.scene==='crypt'){if(Math.hypot(state.x-242,state.y-104)<30&&!state.memories.includes('first-burial')){state.memories.push('first-burial');save();refreshQuest();showToast('A memory returns: you opened the grave. You cannot remember whose name was inside.');return}if(Math.hypot(state.x-700,state.y-245)<42){state.scene='parish';state.x=700;state.y=280;save();refreshQuest();showToast('The rain has not stopped. The parish remembers nothing.');return}showToast('The dead thing draws nearer.');return}let best=-1,dist=Infinity;deathTolls.forEach((f,i)=>{if(!state.tolls.includes(i)){const d=Math.hypot(state.x-f.x,state.y-f.y);if(d<dist){dist=d;best=i}}});if(best>=0&&dist<31){state.tolls.push(best);save();refreshQuest();showToast(state.tolls.length===3?'Three iron tolls. The chapel altar waits in the rain.':'A cold iron death-toll. Its inscription has been scraped away.');return}
  const altarDist=Math.hypot(state.x-700,state.y-245);if(altarDist<40){if(state.bellAnswered){state.scene='crypt';state.x=240;state.y=220;state.wraith={x:170,y:170};save();refreshQuest();showToast(state.memories.includes('first-burial')?'The stair opens again. The dark remembers nothing.':'Steps descend into the earth. Something below has heard you.');return}if(state.tolls.length>=3){state.bellAnswered=true;save();refreshQuest();showToast('The bell tolls once. No hand touched its rope.');return}showToast(`The altar is incomplete. ${3-state.tolls.length} death-toll${state.tolls.length===2?'':'s'} remain in the graves.`);return}
  if(Math.hypot(state.x-514,state.y-359)<38){showToast(state.tolls.length>=3?'Edda: Put them on the altar. And do not answer if it calls your name.':'Edda: Three tolls were buried with the parish dead. I heard one ring last night.');return}showToast('Rain, ash, and the distant sound of a bell.');
}

