await call('Input.dispatchKeyEvent',{type:'keyDown',key:'e',code:'KeyE',windowsVirtualKeyCode:69,nativeVirtualKeyCode:69}); await call('Input.dispatchKeyEvent',{type:'keyUp',key:'e',code:'KeyE',windowsVirtualKeyCode:69,nativeVirtualKeyCode:69}); await pause(100);
const line1 = await evaluate(`({open:dialogueOpen,text:document.getElementById('dialogue-text').textContent})`);
for(let i=0;i<2;i++){await call('Input.dispatchKeyEvent',{type:'keyDown',key:'e',code:'KeyE',windowsVirtualKeyCode:69,nativeVirtualKeyCode:69}); await call('Input.dispatchKeyEvent',{type:'keyUp',key:'e',code:'KeyE',windowsVirtualKeyCode:69,nativeVirtualKeyCode:69}); await pause(80);}
