const { createRequire } = require('node:module');
const { readFileSync } = require('node:fs');
const requireFromRuntime = createRequire(`${process.env.HOME}/.local/share/omgithub-playwright/package.json`);
const { chromium } = requireFromRuntime('playwright');
(async () => {
  const config = JSON.parse(readFileSync(`${process.env.HOME}/.local/share/omgithub-playwright/linux.json`, 'utf8'));
  if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(`${process.env.HOME}/.local/share/omgithub-playwright/display`, 'utf8').trim();
  const browser = await chromium.launch(config.browser.launchOptions);
  try {
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    await page.goto('http://localhost:3002', { waitUntil: 'load' });
    await page.locator('#answer-call').click();
    if (await page.locator('#dream-dialogue').isVisible()) throw new Error('Dialogue appeared before the 2s delay');
    await page.waitForTimeout(2100);
    const line0 = await page.locator('#dialogue-text').textContent();
    if (!line0?.includes('answered my call')) throw new Error(`Unexpected opening line: ${line0}`);
    await page.locator('#dream-dialogue').click();
    if (await page.locator('#dream-dialogue').isVisible()) throw new Error('Expected the 2s collapse pause after Media’s first line');
    const collapse = await page.locator('#collapse-wash').evaluate(el => getComputedStyle(el).getPropertyValue('--collapse'));
    if (!parseFloat(collapse)) throw new Error('Collapse effect did not begin after first line');
    await page.waitForFunction(() => document.querySelector('#dialogue-text')?.textContent.includes('Welcome, lost soul'), { timeout: 4000 });
    for (let i = 1; i < 17; i++) await page.locator('#dream-dialogue').click();
    if (!(await page.locator('#system-trigger').isVisible())) throw new Error('System button did not appear at the final gift line');
    await page.locator('#system-trigger').click();
    if (!(await page.locator('#system-backdrop').isVisible())) throw new Error('System window did not open');
    if (!(await page.locator('#system-title').textContent()).includes('Soulbound')) throw new Error('Unexpected System window title');
    await page.locator('#system-close').click();
    for (let i = 17; i < 21; i++) await page.locator('#dream-dialogue').click();
    await page.waitForFunction(() => !document.querySelector('#dream-dialogue').classList.contains('open'), { timeout: 7000 });
    if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
    console.log('Browser flow passed: delayed opening, first-line collapse pause, gift/System UI, and automatic transport.');
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exit(1); });
